const fn = new Function(code + "\nreturn { bisect };");
const { bisect } = fn();
const cs = ["c1", "c2", "c3", "c4", "c5", "c6", "c7", "c8"];
const badAt = (n) => (id) => Number(id.slice(1)) >= n;
if (bisect(cs, badAt(6)) !== "c6") throw new Error("Found c6, the first bad one.");
if (bisect(cs, badAt(1)) !== "c1") throw new Error("Everything bad => c1.");

const fn = new Function(code + "\nreturn { bisect };");
const { bisect } = fn();
let probes = 0;
const cs = Array.from({ length: 1024 }, (_, i) => "c" + (i + 1));
const found = bisect(cs, (id) => { probes++; return Number(id.slice(1)) >= 777; });
if (found !== "c777") throw new Error("Correct answer first.");
if (probes > 12) throw new Error("1024 commits need ~10 probes, not 777.");
